Lemma upds_nth : forall (l : list Z) (ws : list word) (i j : nat), (i + length l <= length ws)%nat ->
  nth_error (upds ws i l) j = if ((i <=? j) && (j <? i + length l))%nat then option_map (Z_to_bv 64) (nth_error l (j - i)) else nth_error ws j.
Proof.
